function n3(n){return String(n).padStart(3,'0')};function cap(s){return String(s||'').split('-').map(x=>x[0]?.toUpperCase()+x.slice(1)).join(' ')};function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};function ptMove(s){return PT_MOVES[s]||'—'};function moveName(s){return `${esc(ptMove(s))} / ${esc(cap(s))}`};function localSprite(id){const t=staticTypes(id)?.[0]||'normal';const col={fire:'#ed854e',water:'#538ad3',grass:'#5caa67',electric:'#e6b735',poison:'#aa73bf',rock:'#a58c6c',ground:'#bb9662',psychic:'#d66a92',dragon:'#756ac4',ice:'#69bdbc',bug:'#8da44f',normal:'#87908d'}[t]||'#7789ab';const symbol=TYPE_ICON[t]||'●';const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100"><rect width="100" height="100" rx="15" fill="#f3f0de"/><circle cx="50" cy="45" r="32" fill="${col}"/><text x="50" y="56" font-size="30" fill="white" text-anchor="middle">${symbol}</text><text x="50" y="92" font-size="13" font-family="Arial" text-anchor="middle" fill="#26344b">#${n3(id)}</text></svg>`;return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)};function sprite(id){return `./sprites/${id}.png`};function fallback(id){return `./sprites/${id}.png`};function img(id){return `<img loading="lazy" src="${sprite(id)}" onerror="this.onerror=null;this.src='${localSprite(id)}'" alt="${esc(name(id))}">`};function name(id){return cap(state.index.find(p=>p.id===id)?.name||NAMES[id]||`#${id}`)};function staticTypes(id){return localData?.pokemon[id]?.types.map(x=>x.type.name)||(id>=1&&id<=151?KANTO_TYPES[id-1]:null)};function tags(ts){return (ts||[]).map(t=>`<span class="tag ${esc(t)}">${TYPE_PT[t]||t}</span>`).join('')};
function typeChip(t,extra=''){return `<span class="type-chip"><span class="type-dot ${esc(t)}">${TYPE_ICON[t]||'•'}</span>${esc(TYPE_PT[t]||t)}${extra?` <b>${esc(extra)}</b>`:''}</span>`}
function chipRow(items){return items.length?`<div class="type-icons">${items.map(x=>typeChip(typeof x==='string'?x:x.type,typeof x==='string'?'':x.mult+'×')).join('')}</div>`:'<span class="note">Nenhum</span>'}
function moveLine(slug,kind=''){return `<span class="move-line"><span>${kind?esc(kind)+' · ':''}${moveName(slug)}</span><span data-mtype="${esc(slug)}"><span class="tag">TIPO…</span></span></span>`}
async function hydrateMoveTypes(root=document){const nodes=[...root.querySelectorAll('[data-mtype]')];if(!nodes.length)return;const slugs=[...new Set(nodes.map(n=>n.dataset.mtype))];let cursor=0;async function worker(){while(cursor<slugs.length){const slug=slugs[cursor++];const m=await moveMetadata(slug);if(!root.isConnected)return;root.querySelectorAll('[data-mtype]').forEach(n=>{if(n.dataset.mtype===slug)n.innerHTML=m.type?tags([m.type]):'<span class="tag">—</span>'})}}await Promise.all(Array.from({length:Math.min(8,slugs.length)},worker))}
async function hydrateDexTypes(ids,token){let cursor=0;async function worker(){while(cursor<ids.length){const id=ids[cursor++];try{const p=await getDetail(id);if(state.tab!=='dex'||state.selected||viewToken!==token)return;const card=el.querySelector(`.poke[data-id="${id}"] .tags`);if(card)card.innerHTML=tags(p.types)}catch{}}}await Promise.all(Array.from({length:Math.min(8,ids.length)},worker))}
function eff(atk,types){return (types||[]).reduce((v,t)=>v*(IMMUNE[atk]?.includes(t)?0:SUPER[atk]?.includes(t)?2:RESIST[atk]?.includes(t)?0.5:1),1)}
async function api(path){
 const d=await dataReady;let result;
 if(path.startsWith('/pokemon?'))result={results:Object.values(d.pokemon).map(p=>({name:p.name}))};
 else if(/^\/pokemon\/\d+\/encounters$/.test(path))result=d.encounters[path.split('/')[2]];
 else if(path.startsWith('/pokemon/')){const p=d.pokemon[path.split('/')[2]];result=p?{...p,stats:p.stats_by_game?.[state.game]||p.stats}:null;}
 else if(path.startsWith('/pokemon-species/'))result=d.species[path.split('/')[2]];
 else if(path.startsWith('/evolution-chain/'))result=d.chains[path.split('/')[2]];
 else if(path.startsWith('/move/'))result=d.moves[path.split('/')[2]];
 else if(path.startsWith('/pokedex/'))result=d.regional[path.split('/')[2]];
 if(result===undefined||result===null)throw Error('Dado local não encontrado: '+path);return result;
}
async function getDetail(id){if(state.details[id]?.moves?.length)return state.details[id];let p;try{p=await api('/pokemon/'+id)}catch(e){if(staticTypes(id)){return state.details[id]={id,name:KANTO_NAMES[id-1].toLowerCase(),types:staticTypes(id),stats:{},moves:[],abilities:[],offline:true}}throw e};const types=p.types.map(t=>t.type.name);const stats=Object.fromEntries(p.stats.map(x=>[x.stat.name,x.base_stat]));const moves=p.moves.flatMap(m=>m.version_group_details.filter(v=>v.version_group.name===GAME[state.game].group).map(v=>({name:m.move.name,method:v.move_learn_method.name,level:v.level_learned_at})));const detail={id,name:p.name,types,stats,moves,abilities:p.abilities.filter(a=>!a.is_hidden).map(a=>abilityLabel(a.ability.name))};state.details[id]=detail;return detail}
async function loadIndex(){state.index=KANTO_INDEX.slice();render();try{const p=await api('/pokemon?limit=386&offset=0');state.index=p.results.map((x,i)=>({id:i+1,name:x.name}));document.getElementById('net').textContent='386 espécies · base local Geração III';render()}catch{state.index=KANTO_INDEX.slice();document.getElementById('net').textContent='Modo offline · Kanto (151)';render()}loadRegional()}
async function loadRegional(){try{const dex=await api('/pokedex/'+GAME[state.game].region);state.regional=dex.pokemon_entries.map(e=>Number(e.pokemon_species.url.match(/\/(\d+)\/$/)?.[1])).filter(n=>n>=1&&n<=386);render()}catch{state.regional=GAME[state.game].region==='kanto'?Array.from({length:151},(_,i)=>i+1):[];render()}}
function header(t,d){return `<h1 class="heading">${t}</h1><p class="sub">${d}</p>`}function render(){if(state.tab!=='dex'&&state.tab!=='journey')journeyReturn=null;const token=++viewToken;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===state.tab)));if(state.tab==='dex'){if(state.selected)renderDetail(state.selected,token);else renderDex()}else if(state.tab==='team')renderTeam(token);else if(state.tab==='types')renderTypes();else if(state.tab==='battle')renderBattle(token);else if(state.tab==='journey')renderJourney();else renderGuide()}
function renderDex(){const dexToken=viewToken;let list=state.index.filter(p=>state.scope==='national'||state.regional.includes(p.id));const term=state.term.trim().toLowerCase();if(term)list=list.filter(p=>p.name.includes(term)||String(p.id)===term);if(state.type)list=list.filter(p=>(state.details[p.id]?.types||staticTypes(p.id)||[]).includes(state.type));const subset=list.slice(0,state.limit);el.innerHTML=header('POKÉDEX — '+GAME[state.game].label,'Regional: espécies da Pokédex local; Nacional: 386 espécies da Geração III. Fichas, golpes, evoluções e sprites disponíveis no pacote offline. A presença na Pokédex não garante captura direta.')+`<div class="tools"><input class="field" id="search" placeholder="Buscar nome ou nº" value="${esc(state.term)}"><select class="field" id="scope"><option value="regional" ${state.scope==='regional'?'selected':''}>Pokédex regional</option><option value="national" ${state.scope==='national'?'selected':''}>Nacional (386)</option></select><select class="field" id="filter"><option value="">Todos os tipos</option>${TYPES.map(t=>`<option value="${t}" ${state.type===t?'selected':''}>${TYPE_PT[t]}</option>`).join('')}</select></div><div class="count">${list.length} espécie(s) · ${state.type?'Filtro aplicado aos tipos disponíveis no catálogo.':'Selecione para ver golpes e adicionar ao time.'}</div><div class="cards">${subset.map(p=>`<button class="poke" data-id="${p.id}"><span class="number">#${n3(p.id)}</span>${img(p.id)}<div class="pokename">${esc(cap(p.name))}</div><div class="tags">${tags(state.details[p.id]?.types||staticTypes(p.id))}</div></button>`).join('')}</div>${subset.length<list.length?'<button class="btn secondary" id="more" style="margin-top:15px">CARREGAR MAIS</button>':''}`;document.getElementById('search').oninput=e=>{state.term=e.target.value;state.limit=36;renderDex();document.getElementById('search').focus();document.getElementById('search').setSelectionRange(state.term.length,state.term.length)};document.getElementById('scope').onchange=e=>{state.scope=e.target.value;state.limit=36;save();render()};document.getElementById('filter').onchange=e=>{state.type=e.target.value;render()};document.getElementById('more')?.addEventListener('click',()=>{state.limit+=36;renderDex()});el.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{dexHistory.length=0;state.selected=+b.dataset.id;render()});hydrateDexTypes(subset.map(p=>p.id),dexToken)}
function groups(p){const level=p.moves.filter(m=>m.method==='level-up').sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name));const machine=p.moves.filter(m=>m.method==='machine');const tm=machine.filter(m=>TMS.includes(m.name)).sort((a,b)=>TMS.indexOf(a.name)-TMS.indexOf(b.name));const hm=machine.filter(m=>HMS.includes(m.name)).sort((a,b)=>HMS.indexOf(a.name)-HMS.indexOf(b.name));const other=p.moves.filter(m=>!['level-up','machine'].includes(m.method));return {level,tm,hm,other}}
function moveType(m){return m?.type||null}function moveCode(m){let i=TMS.indexOf(m);if(i>=0)return `TM${n3(i+1).slice(1)}`;i=HMS.indexOf(m);return i>=0?`HM${n3(i+1).slice(1)}`:''}
function gen3Class(type,power){if(power===null||power===0)return 'Status';return ['normal','fighting','flying','poison','ground','rock','bug','ghost','steel'].includes(type)?'Físico':'Especial'}
function moveStats(m){if(!m||!m.type)return '<span class="move-stat">Detalhes indisponíveis</span>';return `${tags([m.type])}<span class="move-stat">Classe: <em>${gen3Class(m.type,m.power)}</em></span><span class="move-stat">Poder: <em>${m.power??'—'}</em></span><span class="move-stat">Precisão: <em>${m.accuracy==null?'—':m.accuracy+'%'}</em></span><span class="move-stat">PP: <em>${m.pp??'—'}</em></span>`}
