async function hydrateMoveStats(root=document){const nodes=[...root.querySelectorAll('[data-move-stats]')];if(!nodes.length)return;const slugs=[...new Set(nodes.map(n=>n.dataset.moveStats))];let cursor=0;async function worker(){while(cursor<slugs.length){const slug=slugs[cursor++];const info=await moveMetadata(slug);if(!root.isConnected)return;root.querySelectorAll('[data-move-stats]').forEach(n=>{if(n.dataset.moveStats===slug)n.innerHTML=moveStats(info)})}}await Promise.all(Array.from({length:Math.min(6,slugs.length)},worker))}
function evolutionDetail(node){return node?.evolution_details?.[0]||null}
function isLegacyEvolutionBlocked(id){return id>151&&id<=386&&state.game==='firered'}
function evoCondition(node){
 const x=evolutionDetail(node);if(!x)return 'Forma inicial';
 const evolved=evoSpeciesId(node);
 if(evolved===266||evolved===268)return 'Subir de nível a partir do Nv. 7; resultado determinado pelo valor de personalidade de Wurmple, não pelo horário';
 if(evolved===292)return 'Surge ao evoluir Nincada para Ninjask no Nv. 20 ou superior, com uma vaga livre na equipe; em FireRed/LeafGreen também é necessária uma Poké Ball na mochila';
 const terms=[];
 if(x.trigger?.name==='trade')terms.push('Trocar com outro jogador');
 else if(x.trigger?.name==='use-item'&&x.item)terms.push('Usar '+(ITEM_PT[x.item.name]||`item especial (${cap(x.item.name)})`));
 else if(x.trigger?.name==='level-up')terms.push(x.min_level?'Subir de nível a partir do Nv. '+x.min_level:'Subir de nível');
 else terms.push(methodPt(x.trigger?.name||''));
 if(x.min_happiness!=null)terms.push('amizade de pelo menos '+x.min_happiness);
 if(x.min_beauty!=null)terms.push('beleza de pelo menos '+x.min_beauty);
 if(x.held_item)terms.push('segurando '+(ITEM_PT[x.held_item.name]||`item (${cap(x.held_item.name)})`));
 if(x.time_of_day)terms.push('no período: '+(x.time_of_day==='day'?'dia':x.time_of_day==='night'?'noite':x.time_of_day));
 if(x.known_move)terms.push('conhecendo '+(PT_MOVES[x.known_move.name]||'golpe')+' ('+cap(x.known_move.name)+')');
 if(x.known_move_type)terms.push('com golpe do tipo '+(TYPE_PT[x.known_move_type.name]||cap(x.known_move_type.name)));
 if(x.location)terms.push('em '+localizedLocation(cap(x.location.name)));
 if(x.gender===1)terms.push('fêmea');if(x.gender===2)terms.push('macho');
 if(x.relative_physical_stats===1)terms.push('Ataque maior que Defesa');
 if(x.relative_physical_stats===-1)terms.push('Defesa maior que Ataque');
 if(x.relative_physical_stats===0)terms.push('Ataque igual à Defesa');
 if(x.needs_overworld_rain||x.turn_upside_down||x.min_affection||x.min_happiness===null&&x.min_beauty===null&&x.trigger?.name==='level-up'&&!x.min_level&&!x.held_item&&!x.time_of_day&&!x.known_move&&!x.location)terms.push('verificar requisitos adicionais');
 return terms.join(' · ');
}
