'effect-spore':['Esporos de Efeito (Effect Spore)','O contato pode causar sono, paralisia ou envenenamento.'],
'illuminate':['Iluminação (Illuminate)','Na Geração III, aumenta a frequência de encontros selvagens fora de batalha.'],
'trace':['Rastreamento (Trace)','Copia a habilidade do adversário ao entrar em batalha.'],
'soundproof':['Isolamento Sonoro (Soundproof)','Protege contra golpes baseados em som.'],
'filter':['Filtro (Filter)','Habilidade de geração posterior; não está disponível no FireRed.'],
'magnet-pull':['Atração Magnética (Magnet Pull)','Impede a fuga ou troca de adversários do tipo Aço em certas condições.'],
'sticky-hold':['Aderência (Sticky Hold)','Impede que o item segurado seja retirado por golpes do adversário.'],
'suction-cups':['Ventosas (Suction Cups)','Impede movimentos que forçam a retirada do campo.'],
'water-absorb':['Absorção de Água (Water Absorb)','Recupera PS ao receber golpes de Água.'],
'ice-body':['Corpo de Gelo (Ice Body)','Habilidade de geração posterior; não está disponível no FireRed.'],
'magma-armor':['Armadura de Magma (Magma Armor)','Impede congelamento.'],
'heatproof':['À Prova de Calor (Heatproof)','Habilidade de geração posterior; não está disponível no FireRed.'],
'shadow-tag':['Sombra Aprisionadora (Shadow Tag)','Impede a fuga ou troca do adversário sob condições específicas.'],
'arena-trap':['Armadilha de Arena (Arena Trap)','Impede a fuga ou troca de adversários vulneráveis à habilidade.'],
'anticipation':['Antecipação (Anticipation)','Habilidade de geração posterior; não está disponível no FireRed.'],
'normalize':['Normalização (Normalize)','Habilidade de geração posterior; não está disponível no FireRed.'],
'plus':['Mais (Plus)','Fortalece o Ataque Especial quando está com um aliado de habilidade Menos.'],
'minus':['Menos (Minus)','Fortalece o Ataque Especial quando está com um aliado de habilidade Mais.'],
'hyper-cutter':['Corte Preciso (Hyper Cutter)','Impede redução do atributo Ataque pelo adversário.'],
'own-tempo':['Ritmo Próprio (Own Tempo)','Impede confusão.'],
'water-veil':['Véu de Água (Water Veil)','Impede queimaduras.'],
'speed-boost':['Aumento de Velocidade (Speed Boost)','Aumenta a Velocidade ao final de cada turno.'],
'shed-skin':['Troca de Pele (Shed Skin)','Pode curar uma alteração de estado ao final do turno.'],
